from itertools import product
def fitset(extra):
    best=None
    for c2 in np.linspace(0.05,1.0,39):
        for c4 in np.linspace(0.005,0.5,40):
            X=np.column_stack([t*np.exp(-c2*t)*A**2, np.exp(-c4*t**2)]+extra)
            b=np.linalg.lstsq(X,dA_dt,rcond=None)[0]
            s=np.sum((dA_dt-X@b)**2)
            if best is None or s<best[0]: best=(s,c2,c4,b)
    return best
